INSERT INTO forms (id, title, description, fields_json, is_active, created_at) VALUES (1, 'Форма № 1: Інформація для проведення аналізу цін (базова)', 'Сформована на основі документа «Інформація для проведення аналізу цін.docx» з додатковими полями очікуваної вартості та обсягу закупівлі.', '[{"key": "buyer_name", "label": "Найменування замовника", "type": "text", "required": true}, {"key": "edrpou", "label": "Код ЄДРПОУ", "type": "text", "required": true}, {"key": "subject_name", "label": "Конкретна назва предмета закупівлі", "type": "text", "required": true}, {"key": "cpv_code", "label": "Код ДК 021:2015 (CPV 2008, IDT)", "type": "text", "required": true}, {"key": "expected_value", "label": "Очікувана вартість предмета закупівлі (без ПДВ, грн)", "type": "number", "required": true}, {"key": "quantity", "label": "Кількість (обсяг закупівлі)", "type": "number", "required": true}, {"key": "unit_name", "label": "Одиниця виміру (Гкал, шт, послуга тощо)", "type": "text", "required": true}, {"key": "tender_id", "label": "Ідентифікатор закупівлі в Prozorro (UA-... за наявності)", "type": "text", "required": false}]', 1, '2026-10-25 08:42:55');
INSERT INTO forms (id, title, description, fields_json, is_active, created_at) VALUES (2, 'Форма № 2: Повна форма Обґрунтування (Постанова № 710 + Аналіз цін Prozorro)', 'Розширена форма з усіма реквізитами замовника, місцями поставки та технічними характеристиками за зразком НУК ім. адм. Макарова.', '[{"key": "tender_id", "label": "Ідентифікатор закупівлі в Prozorro (UA-...)", "type": "text", "required": true}, {"key": "plan_id", "label": "Ідентифікатор плану закупівлі в Prozorro", "type": "text", "required": false}, {"key": "buyer_name", "label": "Найменування замовника", "type": "text", "required": true}, {"key": "edrpou", "label": "Код ЄДРПОУ замовника", "type": "text", "required": true}, {"key": "buyer_address", "label": "Місцезнаходження (юридична адреса) замовника", "type": "text", "required": true}, {"key": "director_title", "label": "Посада керівника (для грифу ЗАТВЕРДЖУЮ)", "type": "text", "required": true}, {"key": "director_name", "label": "Власне ім''я ПРІЗВИЩЕ керівника", "type": "text", "required": true}, {"key": "authorized_person", "label": "Власне ім''я ПРІЗВИЩЕ уповноваженої особи", "type": "text", "required": true}, {"key": "phone", "label": "Телефон уповноваженої особи", "type": "text", "required": false}, {"key": "website", "label": "Офіційний веб-сайт замовника (для оприлюднення за Постановою № 710)", "type": "text", "required": false}, {"key": "subject_name", "label": "Конкретна назва предмета закупівлі", "type": "text", "required": true}, {"key": "cpv_code", "label": "Код ДК 021:2015 (CPV)", "type": "text", "required": true}, {"key": "quantity", "label": "Кількість (плановий обсяг закупівлі)", "type": "number", "required": true}, {"key": "unit_name", "label": "Одиниця виміру", "type": "text", "required": true}, {"key": "expected_value", "label": "Очікувана вартість предмета закупівлі (без ПДВ, грн)", "type": "number", "required": true}, {"key": "kekv", "label": "Код економічної класифікації видатків (КЕКВ)", "type": "text", "required": false}, {"key": "delivery_term", "label": "Строк поставки товарів / надання послуг", "type": "text", "required": false}, {"key": "delivery_address", "label": "Місця поставки (кожна адреса з нового рядка)", "type": "textarea", "required": false}, {"key": "tech_specs", "label": "Технічні та якісні характеристики предмета закупівлі", "type": "textarea", "required": false}]', 1, '2026-10-25 08:42:55');